// ============================================
// EMAIL TRIAGE — Node 1: Bereinigung (robust)
// ============================================

const mail = $input.first().json;

// ---------- HELFER: Absender-Adresse finden ----------
function findSenderAddress(m) {
  const candidates = [
    m?.from?.emailAddress?.address,
    m?.sender?.emailAddress?.address,
    m?.from?.address,
    m?.sender?.address,
    m?.fromAddress,
    typeof m?.from === "string" ? m.from : null,
    typeof m?.sender === "string" ? m.sender : null,
  ];
  for (const c of candidates) {
    if (typeof c === "string" && c.includes("@")) return c.trim();
  }
  return "";
}

function findSenderName(m) {
  const candidates = [
    m?.from?.emailAddress?.name,
    m?.sender?.emailAddress?.name,
    m?.from?.name,
  ];
  for (const c of candidates) {
    if (typeof c === "string" && c.trim()) return c.trim();
  }
  return "";
}

// ---------- FELDER ----------
const subject    = mail.subject || "(kein Betreff)";
const sender     = findSenderAddress(mail);
const senderName = findSenderName(mail) || sender || "Unbekannt";
const rawBody    = mail.body?.content || mail.bodyPreview || "";

// ---------- HTML ENTFERNEN ----------
let cleanBody = rawBody
  .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, " ")
  .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, " ")
  .replace(/<[^>]+>/g, " ")
  .replace(/&nbsp;/g, " ")
  .replace(/&amp;/g, "&")
  .replace(/&lt;/g, "<")
  .replace(/&gt;/g, ">")
  .replace(/&quot;/g, '"')
  .replace(/&#39;/g, "'")
  .replace(/\s+/g, " ")
  .trim();

// ---------- ZITIERTEN VERLAUF ABSCHNEIDEN ----------
const cutoffs = [
  /Von:\s.*Gesendet:/i,
  /-----Ursprüngliche Nachricht-----/i,
  /On .* wrote:/i,
  /Am .* schrieb .*:/i,
];
for (const pattern of cutoffs) {
  const match = cleanBody.match(pattern);
  if (match) {
    cleanBody = cleanBody.slice(0, match.index).trim();
    break;
  }
}

cleanBody = cleanBody.slice(0, 1500);
if (!cleanBody) cleanBody = "(kein lesbarer Inhalt)";

const debugFrom = JSON.stringify(mail.from || mail.sender || {});

return [{
  json: {
    subject,
    sender,
    senderName,
    cleanBody,
    mailId: mail.id,
    receivedAt: mail.receivedDateTime,
    tenant_id: mail.tenant_id,
    telegram_chat_id: mail.telegram_chat_id,
    _debugFrom: debugFrom,
  }
}];

// ============================================
// EMAIL TRIAGE — Node 3: Claude-Antwort parsen
// ============================================
const apiResponse = $input.first().json;
const raw = apiResponse.text || '';
let parsed;
try {
  const clean = raw.replace(/```json|```/g, '').trim();
  const start = clean.indexOf('{');
  const end   = clean.lastIndexOf('}');
  parsed = JSON.parse(clean.slice(start, end + 1));
} catch (e) {
  parsed = {
    kategorie: 'NORMAL',
    zusammenfassung: raw.slice(0, 120) || 'Konnte nicht analysiert werden',
    antwort_noetig: true,
    draft: raw,
  };
}
const orig = $('Mail bereinigen').item.json;
let kategorie      = parsed.kategorie || 'NORMAL';
let antwort_noetig = parsed.antwort_noetig !== false;
// 22.10.2026 -- Automail-Guard: LEAD von System-/noreply-Absendern ist nie ein echter Lead (deterministisch, nicht nur dem LLM ueberlassen).
const AUTO_SENDER = /^(no[-_.]?reply|do[-_.]?not[-_.]?reply|notifications?|newsletter|mailer-daemon|postmaster|bounces?|alerts?)([@+._-]|$)/i;
const senderLocal = String(orig.sender || '').split('@')[0];
const autoSenderDowngrade = kategorie === 'LEAD' && AUTO_SENDER.test(senderLocal);
if (autoSenderDowngrade) { kategorie = 'INFO'; antwort_noetig = false; }
// 24.09.2026 -- Privat/Geschaeftlich-Gate: dieses Postfach wird fuer beides genutzt.
// autoSendOk wird HIER deterministisch berechnet, nicht dem LLM allein ueberlassen --
// gleiches Prinzip wie bei den Wochentag-Fixes: sicherheitskritische UND-Bedingung nie
// nur dem LLM-Output vertrauen.
const bereich = parsed.bereich === 'geschaeftlich' ? 'geschaeftlich' : 'privat';
const autoSendOk = !autoSenderDowngrade && bereich === 'geschaeftlich' && parsed.routine === true;
const shouldPush =
  kategorie === 'WICHTIG' ||
  kategorie === 'LEAD' ||
  (kategorie === 'NORMAL' && antwort_noetig === true);
return [{
  json: {
    kategorie,
    zusammenfassung: parsed.zusammenfassung || '',
    antwort_noetig,
    draft:           autoSenderDowngrade ? '' : (parsed.draft || ''),
    bereich,
    autoSendOk,
    subject:         orig.subject,
    sender:          orig.sender,
    senderName:      orig.senderName,
    mailId:          orig.mailId,
    tenant_id:        orig.tenant_id,
    telegram_chat_id: orig.telegram_chat_id,
    shouldPush
  }
}];

